'use server'

import { revalidatePath } from 'next/cache'

// Simulated user notification preference storage
// In a real app, this would be in a database
let userNotificationPreference = true

export async function getUserNotificationPreference() {
  // Simulate fetching from database
  return userNotificationPreference
}

export async function toggleNotificationPreference() {
  // Toggle the preference
  userNotificationPreference = !userNotificationPreference

  // Revalidate the current page to refresh without redirect
  revalidatePath('/')

  return {
    success: true,
    newPreference: userNotificationPreference
  }
}

